mapper.select:
WITH base AS ( SELECT s.send_log_id, s.customer_id, s.status FROM send_log s WHERE s.kind = 'CAMPAIGN' AND s.status IN ('SENT', 'BOUNCED', 'FAILED')
AND s.campaign_id = #{campaignId}
AND s.step_id = #{stepId}
AND COALESCE(s.sent_at, s.updated_at) >= #{from}
AND COALESCE(s.sent_at, s.updated_at) < #{to}
), sent AS ( SELECT send_log_id, customer_id FROM base WHERE status = 'SENT' ) SELECT (SELECT count(*) FROM base) AS attempted, (SELECT count(*) FROM sent) AS sent, (SELECT count(DISTINCT x.customer_id) FROM sent x WHERE EXISTS (SELECT 1 FROM track_event e WHERE e.send_log_id = x.send_log_id AND e.event_type = 'OPEN' AND e.bot_yn = 'N')) AS unique_opens, (SELECT count(DISTINCT x.customer_id) FROM sent x WHERE EXISTS (SELECT 1 FROM track_event e WHERE e.send_log_id = x.send_log_id AND e.event_type = 'CLICK' AND e.bot_yn = 'N')) AS unique_clicks, (SELECT count(DISTINCT x.customer_id) FROM sent x JOIN coupon_issue ci ON ci.send_log_id = x.send_log_id WHERE ci.used_at IS NOT NULL) AS coupon_used

SELECT e.event_id, e.event_type, e.occurred_at, s.campaign_id, c.name AS campaign_name, cu.name AS customer_name FROM track_event e JOIN send_log s ON s.send_log_id = e.send_log_id LEFT JOIN campaign c ON c.campaign_id = s.campaign_id LEFT JOIN customer cu ON cu.customer_id = s.customer_id WHERE e.bot_yn = 'N' AND s.kind = 'CAMPAIGN'
AND e.event_id > #{after}
ORDER BY e.event_id DESC LIMIT #{limit}
